export function guidedLabel(definition: CatalogDefinition) { return labelTranslations[definition.label] ?? definition.label; }

function evidenceFor(role: Role): Evidence {
  const today = new Date().toISOString().slice(0, 10);
  return { sourceType: role === "ADMIN" ? "ADMIN_OBSERVATION" : "OWNER_CLAIM", sourceName: role === "ADMIN" ? "Geführte Admin-Erfassung" : "Philipps Casa · verifizierter Owner", observedAt: today, validFrom: today, validUntil: "", verificationState: role === "ADMIN" ? "UNVERIFIED" : "PENDING", reference: "Automatisch aus der geführten Erfassung angelegt.", stance: "SUPPORTS", privateReference: false };
}

function definitionsFor(step: GuidedStepId, state: PrototypeState) {
  const categories = new Set([state.spot.primaryCategory, ...state.spot.secondaryCategories]);
  return catalog.definitions.filter((item) => {
    if (!item.applicableCategories.some((key) => categories.has(key))) return false;
    if (step === "place-type") return item.semanticClass === "SUBCATEGORY";
    if (step === "cuisine") return item.semanticClass === "CUISINE";
    if (step === "offering") return item.semanticClass === "OFFERING" || item.id === "character-service-model";
    if (step === "capabilities") return item.semanticClass === "CAPABILITY";
    if (step === "situation") return item.semanticClass === "DIRECT_FIT" && !["Group Size Fit", "Visit Length Fit", "Weather Fit", "Companion Fit", "Planning Fit"].includes(item.family);
    if (step === "amenities") {
      if (["STRUCTURED", "STRUCTURED_COMPOSITE"].includes(item.valueType) && item.id !== "character-noise") return false;
      if (item.family === "Constraints / Operational Constraints") return false;
      if (["Alkohol nur ab bestimmtem Alter", "maximale Gruppengröße", "Küche schließt früher als Venue", "Reservation erforderlich", "Barrierefrei zugänglich"].includes(item.label)) return false;
      return item.group === "AMENITIES_CONSTRAINTS" || item.group === "CHARACTERISTICS";
    }
    return false;
  });
}

function selectedIds(state: PrototypeState) { return new Set(resolveKnowledge(state).filter((item) => item.status === "KNOWN_TRUE" || item.status === "KNOWN_VALUE").map((item) => item.definition.id)); }
function activeClaim(state: PrototypeState, definitionId: string) {
  const retracted = new Set(state.claims.filter((claim) => claim.operation === "RETRACT").map((claim) => claim.supersedesClaimId));
  return [...state.claims].reverse().find((claim) => claim.definitionId === definitionId && claim.operation !== "RETRACT" && !retracted.has(claim.id));
}
function appendGuidedClaim(state: PrototypeState, definition: CatalogDefinition, role: Role, status?: ClaimStatus, value?: unknown) {
  const previous = activeClaim(state, definition.id); const claims = [...state.claims]; const createdAt = new Date().toISOString();
  if (previous) claims.push({ id: crypto.randomUUID(), definitionId: definition.id, status: "UNKNOWN", value: null, actor: role, createdAt, evidence: evidenceFor(role), operation: "RETRACT", supersedesClaimId: previous.id });
  if (status) claims.push({ id: crypto.randomUUID(), definitionId: definition.id, status, value: status === "KNOWN_TRUE" ? true : status === "KNOWN_FALSE" ? false : status === "KNOWN_VALUE" ? value : null, actor: role, createdAt, evidence: evidenceFor(role), operation: "ASSERT" });
  return claims;
}

const priority: Record<string, string[]> = {
  "place-type": ["Restaurant", "Brasserie", "Bistro", "Café", "Cafe", "Pub", "Imbiss", "Take Away", "Fast-Food", "Bar", "Bakery"],
  cuisine: ["Swiss", "Italian", "French", "Mediterranean", "Asian", "Japanese", "Burger", "Pizza"],
  offering: ["Casual Dining", "Fine Dining", "Fast Casual", "Farm-to-Table", "Street Food", "Buffet", "Patisserie", "Service-Modell"],
  capabilities: ["Breakfast", "Brunch", "Lunch", "Dinner", "Coffee", "Tea", "Wine", "Full meal", "Quick meal", "Group gathering", "Work-friendly"],
  situation: ["Date", "Freunde", "Familie", "Alleine", "Kleine Gruppe", "Große Gruppe", "Ruhig", "Gemütlich", "Lebhaft", "Arbeiten"],
  amenities: ["WLAN", "Steckdosen", "Terrasse", "überdachte Außenplätze", "Rollstuhl-WC", "Hochstuhl", "Reservation online", "stufenloser Zugang"],
};

export function GuidedWorkflow({ state, setState, role, onSave, onAnalyze, onOpenExpert }: { state: PrototypeState; setState: Dispatch<SetStateAction<PrototypeState>>; role: Role; onSave(): void; onAnalyze(): void; onOpenExpert(): void }) {
  const [step, setStep] = useState<GuidedStepId>("basics"); const headingRef = useRef<HTMLHeadingElement>(null); const currentIndex = guidedSteps.findIndex((item) => item.id === step); const current = guidedSteps[currentIndex]; const selected = useMemo(() => selectedIds(state), [state]);
  const navigate = (next: GuidedStepId) => { setState((value) => ({ ...value, guidedProgress: { ...value.guidedProgress, visitedSteps: [...new Set([...value.guidedProgress.visitedSteps, next])] } })); setStep(next); requestAnimationFrame(() => headingRef.current?.focus()); };
  const skip = () => { setState((value) => ({ ...value, guidedProgress: { ...value.guidedProgress, skippedSteps: [...new Set([...value.guidedProgress.skippedSteps, step])] } })); if (currentIndex < guidedSteps.length - 1) navigate(guidedSteps[currentIndex + 1].id); };
  const next = () => currentIndex < guidedSteps.length - 1 ? navigate(guidedSteps[currentIndex + 1].id) : onAnalyze();
  const clear = (definition: CatalogDefinition) => { if (!isUnlocked(definition, role)) return; setState((currentState) => ({ ...currentState, claims: appendGuidedClaim(currentState, definition, role) })); };
  const toggle = (definition: CatalogDefinition) => { if (definition.valueType !== "BOOLEAN" || !isUnlocked(definition, role)) return; setState((currentState) => ({ ...currentState, claims: appendGuidedClaim(currentState, definition, role, selected.has(definition.id) ? undefined : "KNOWN_TRUE") })); };
  const setValue = (definition: CatalogDefinition, value: unknown) => { if (!isUnlocked(definition, role)) return; setState((currentState) => ({ ...currentState, claims: appendGuidedClaim(currentState, definition, role, "KNOWN_VALUE", value) })); };
  const setUnknown = (definition: CatalogDefinition) => { if (!isUnlocked(definition, role)) return; setState((currentState) => ({ ...currentState, claims: appendGuidedClaim(currentState, definition, role, "UNKNOWN") })); };
  return <div className="wk-guide-layout"><aside className="wk-guide-steps" aria-label="Schritte der Spot-Erfassung"><div className="wk-guide-progress"><span>Spot-Erfassung</span><strong>Schritt {currentIndex + 1} von {guidedSteps.length}</strong><i><b style={{ width: `${((currentIndex + 1) / guidedSteps.length) * 100}%` }} /></i></div><nav>{guidedSteps.map((item, index) => { const count = item.id === "basics" || item.id === "review" || item.id === "category" ? 0 : definitionsFor(item.id, state).filter((definition) => selected.has(definition.id)).length; const skipped = state.guidedProgress.skippedSteps.includes(item.id); const visited = state.guidedProgress.visitedSteps.includes(item.id); const basicsComplete = Boolean(state.spot.name && state.spot.address && state.spot.city); const summary = item.id === "basics" ? (basicsComplete ? "Grundinformationen vollständig" : "Notwendige Angaben prüfen") : item.id === "category" ? `${catalog.categories.find((entry) => entry.key === state.spot.primaryCategory)?.label ?? "Noch wählen"} ausgewählt` : item.id === "review" ? "Angaben und technische Hinweise prüfen" : count ? `${count} ${count === 1 ? "Angabe" : "Angaben"} ausgewählt` : skipped ? "Später ausfüllen" : visited ? "Noch nichts ausgewählt" : "Noch nicht bearbeitet"; return <button type="button" key={item.id} data-active={step === item.id} onClick={() => navigate(item.id)}><span>{index + 1}</span><div><strong>{item.label}</strong><small>{summary}</small></div></button>; })}</nav><button className="wk-open-expert" type="button" onClick={onOpenExpert}>Erweiterte Angaben und Quellen <span>→</span></button></aside>
    <main className="wk-guide-main"><div className="wk-guide-intro"><div><span className="wk-kicker">PHILIPPS CASA BESCHREIBEN</span><h1 ref={headingRef} tabIndex={-1}>{current.title}</h1><p>{current.help}</p></div><div className="wk-guide-reminder"><strong>Du musst nicht alles ausfüllen.</strong><span>Wähle nur aus, was wirklich auf den Spot zutrifft. Alles andere kann offenbleiben.</span></div></div>{state.migration.reviewDefinitionIds.length > 0 && <div className="wk-migration-note"><strong>Frühere Eingaben wurden erhalten.</strong><span>{state.migration.notice}</span></div>}{step === "basics" && <Basics state={state} setState={setState} role={role} selected={selected} onToggle={toggle} />}{step === "category" && <CategoryStep state={state} setState={setState} />}{(["place-type", "cuisine", "offering", "capabilities", "situation", "amenities"] as GuidedStepId[]).includes(step) && <SelectionStep step={step} state={state} role={role} selected={selected} onToggle={toggle} onClear={clear} onValue={setValue} onUnknown={setUnknown} />}{step === "review" && <Review state={state} onSave={onSave} onAnalyze={onAnalyze} onOpenExpert={onOpenExpert} />}<footer className="wk-guide-actions"><button type="button" className="wk-guide-secondary" onClick={skip} disabled={step === "review" || step === "category"}>Später ausfüllen</button><span>Deine bisherigen Angaben bleiben erhalten.</span><button type="button" className="wk-guide-next" onClick={next}>{step === "review" ? "Analyse starten" : "Weiter"} <span>→</span></button></footer></main></div>;
}

function CategoryStep({ state, setState }: { state: PrototypeState; setState: Dispatch<SetStateAction<PrototypeState>> }) {
  return <section className="wk-guide-card"><div className="wk-category-choice"><p>Genau eine Hauptkategorie ist aktiv. Bereits erfasste Angaben bleiben bei einem Wechsel erhalten und werden nicht still gelöscht.</p><div>{catalog.categories.map((category) => <button type="button" key={category.key} aria-pressed={state.spot.primaryCategory === category.key} data-selected={state.spot.primaryCategory === category.key} onClick={() => setState((current) => ({ ...current, spot: { ...current.spot, primaryCategory: category.key } }))}><span aria-hidden="true">{state.spot.primaryCategory === category.key ? "✓" : ""}</span><strong>{category.label}</strong></button>)}</div></div></section>;
}

const paymentChoices = ["Bargeld", "Kartenzahlung", "Mobile Payment", "Rechnung möglich"];

function Basics({ state, setState, role, selected, onToggle }: { state: PrototypeState; setState: Dispatch<SetStateAction<PrototypeState>>; role: Role; selected: Set<string>; onToggle(definition: CatalogDefinition): void }) {
  const patchSpot = (patch: Partial<PrototypeState["spot"]>) => setState((current) => ({ ...current, spot: { ...current.spot, ...patch } })); const relevant = catalog.definitions.filter((item) => item.applicableCategories.includes(state.spot.primaryCategory));
  const payments = relevant.filter((item) => paymentChoices.includes(item.label)); const takeawayDefinition = relevant.find((item) => item.semanticClass === "CAPABILITY" && item.label === "Takeaway");
  const setTakeaway = (value: PrototypeState["spot"]["takeaway"]) => setState((current) => ({ ...current, spot: { ...current.spot, takeaway: value }, claims: takeawayDefinition ? appendGuidedClaim(current, takeawayDefinition, role, value === "YES" ? "KNOWN_TRUE" : value === "NO" ? "KNOWN_FALSE" : undefined) : current.claims }));
  return <section className="wk-guide-card wk-basics-stack"><BasicSection title="Identität und Standort" help="Name und Adresse bilden den notwendigen Grundrahmen. Die Hauptkategorie folgt im nächsten Schritt."><div className="wk-friendly-fields"><label><span>Name <em>notwendig</em></span><input value={state.spot.name} onChange={(event) => patchSpot({ name: event.target.value })} /></label><label className="wide"><span>Adresse <em>notwendig</em></span><input value={state.spot.address} onChange={(event) => patchSpot({ address: event.target.value })} /></label><label><span>Ort</span><input value={state.spot.city} onChange={(event) => patchSpot({ city: event.target.value })} /></label><label><span>Quartier</span><input value={state.spot.neighborhood} onChange={(event) => patchSpot({ neighborhood: event.target.value })} placeholder="z. B. Kreis 4" /></label></div>{state.spot.secondaryCategories.length > 0 && <p className="wk-preserved-note">{state.spot.secondaryCategories.length} frühere Zusatzkategorie(n) wurden zur Datenintegrität erhalten, beeinflussen den normalen Erfassungsweg aber nicht.</p>}</BasicSection>
    <BasicSection title="Kontakt und Kanäle" help="Nur öffentliche Angaben eintragen, die Gäste verwenden dürfen."><div className="wk-friendly-fields"><label><span>Webseite</span><input type="url" value={state.spot.website} onChange={(event) => patchSpot({ website: event.target.value })} placeholder="https://…" /></label><label><span>Telefonnummer</span><input type="tel" value={state.spot.phone} onChange={(event) => patchSpot({ phone: event.target.value })} placeholder="+41 …" /></label><label><span>Instagram</span><input value={state.spot.instagram} onChange={(event) => patchSpot({ instagram: event.target.value })} placeholder="@philipps.casa" /></label><label><span>Facebook</span><input value={state.spot.facebook} onChange={(event) => patchSpot({ facebook: event.target.value })} /></label><label><span>LinkedIn</span><input value={state.spot.linkedin} onChange={(event) => patchSpot({ linkedin: event.target.value })} /></label><label><span>TikTok</span><input value={state.spot.tiktok} onChange={(event) => patchSpot({ tiktok: event.target.value })} placeholder="@philipps.casa" /></label></div></BasicSection>
    <BasicSection title="Profil und Bezahlung" help="Wähle nur passende Angaben. Nicht ausgewählte Einträge sind keine Lücken."><div className="wk-friendly-fields"><label className="wide"><span>Besonderheit</span><textarea value={state.spot.specialFeature} onChange={(event) => patchSpot({ specialFeature: event.target.value })} placeholder="Was macht Philipps Casa besonders?" rows={3} /></label><label><span>Preislevel</span><select value={state.spot.priceLevel} onChange={(event) => patchSpot({ priceLevel: event.target.value })}><option value="">Noch nicht angegeben</option><option value="$">$ · günstig</option><option value="$$">$$ · mittel</option><option value="$$$">$$$ · gehoben</option><option value="$$$$">$$$$ · exklusiv</option></select></label><fieldset className="wk-inline-radios"><legend>Take-away</legend>{[["YES", "Ja"], ["NO", "Nein"], ["UNKNOWN", "Noch offen"]].map(([value, label]) => <label key={value}><input type="radio" name="takeaway" checked={state.spot.takeaway === value} onChange={() => setTakeaway(value as PrototypeState["spot"]["takeaway"])} />{label}</label>)}</fieldset></div><CompactPicker title="Bezahlarten" definitions={payments} selected={selected} role={role} onToggle={onToggle} /></BasicSection>
    <BasicSection title="Öffnungszeiten" help="Reguläre Zeiten, Sondertage und der heutige Status gehören direkt zu den Grundinformationen."><FriendlyHours state={state} setState={setState} /></BasicSection></section>;
}

function BasicSection({ title, help, children }: { title: string; help: string; children: React.ReactNode }) { return <section className="wk-basic-section"><div className="wk-basic-heading"><h2>{title}</h2><p>{help}</p></div>{children}</section>; }
function CompactPicker({ title, definitions, selected, role, onToggle }: { title: string; definitions: CatalogDefinition[]; selected: Set<string>; role: Role; onToggle(definition: CatalogDefinition): void }) { if (!definitions.length) return null; return <div className="wk-compact-picker"><h3>{title}</h3><div>{definitions.map((definition) => <button type="button" key={definition.id} aria-pressed={selected.has(definition.id)} data-selected={selected.has(definition.id)} disabled={!isUnlocked(definition, role)} onClick={() => onToggle(definition)}>{selected.has(definition.id) && <span aria-hidden="true">✓</span>}{guidedLabel(definition)}</button>)}</div></div>; }

function SelectionStep({ step, state, role, selected, onToggle, onClear, onValue, onUnknown }: { step: GuidedStepId; state: PrototypeState; role: Role; selected: Set<string>; onToggle(definition: CatalogDefinition): void; onClear(definition: CatalogDefinition): void; onValue(definition: CatalogDefinition, value: unknown): void; onUnknown(definition: CatalogDefinition): void }) {
  const [search, setSearch] = useState(""); const [expanded, setExpanded] = useState(false); const [editingId, setEditingId] = useState<string | null>(null); const all = useMemo(() => definitionsFor(step, state), [step, state]);
  const resolvedValues = useMemo(() => new Map(resolveKnowledge(state).map((item) => [item.definition.id, item.value])), [state]);
  const ordered = useMemo(() => [...all].sort((a, b) => { const labels = priority[step] ?? []; const ai = labels.indexOf(a.label); const bi = labels.indexOf(b.label); return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi) || guidedLabel(a).localeCompare(guidedLabel(b), "de"); }), [all, step]);
  const matching = ordered.filter((item) => !search || `${guidedLabel(item)} ${familyTranslations[item.family] ?? item.family}`.toLocaleLowerCase("de").includes(search.toLocaleLowerCase("de"))); const shown = matching.slice(0, expanded || search ? 250 : step === "place-type" ? 16 : 18); const selectedDefinitions = all.filter((item) => selected.has(item.id)); const clusters = Object.entries(shown.reduce<Record<string, CatalogDefinition[]>>((groups, item) => { const key = step === "cuisine" ? "Küchenrichtungen" : step === "offering" ? (item.id === "character-service-model" ? "Bedienung und Service" : familyTranslations[item.family] ?? "Angebotsform") : familyTranslations[item.family] ?? item.family; groups[key] = [...(groups[key] ?? []), item]; return groups; }, {}));
  return <section className="wk-guide-card"><div className="wk-picker-toolbar"><label><span>In diesem Bereich suchen</span><input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Begriff eingeben …" /></label>{selectedDefinitions.length > 0 && <div className="wk-selected-summary"><span>Ausgewählt</span><strong>{selectedDefinitions.length}</strong></div>}</div>{step === "situation" && <p className="wk-picker-guidance">Hier stehen nur direkte, subjektive Eindrücke. Wetter-, Gruppen- und Aufenthalts-Eignung leitet Backyrd vorsichtig aus konkreten Fakten ab.</p>}{selectedDefinitions.length > 0 && <div className="wk-selected-chips">{selectedDefinitions.map((item) => <button type="button" key={item.id} onClick={() => onClear(item)}>{guidedLabel(item)}{item.valueType !== "BOOLEAN" && <small>{formatGuidedValue(item, resolvedValues.get(item.id))}</small>}<span aria-hidden="true">×</span><span className="sr-only"> entfernen</span></button>)}</div>}<div className="wk-cluster-list">{clusters.map(([title, definitions]) => <OptionGroup title={title} definitions={definitions} selected={selected} role={role} onToggle={onToggle} onClear={onClear} onValue={onValue} onUnknown={onUnknown} resolvedValues={resolvedValues} editingId={editingId} setEditingId={setEditingId} key={title} />)}</div>{!shown.length && <div className="wk-guide-empty">Keine passende Option gefunden. Im erweiterten Bereich bleibt der vollständige Katalog verfügbar.</div>}{!expanded && !search && ordered.length > shown.length && <button type="button" className="wk-show-more" onClick={() => setExpanded(true)}>Alle {ordered.length} Möglichkeiten anzeigen</button>}{expanded && !search && ordered.length > 18 && <button type="button" className="wk-show-more" onClick={() => setExpanded(false)}>Auf häufige Möglichkeiten reduzieren</button>}<p className="wk-picker-footnote">Nicht ausgewählt bedeutet hier nur: keine Aussage gemacht. Es bedeutet nicht „trifft nicht zu“.</p></section>;
}

function formatGuidedValue(definition: CatalogDefinition, value: unknown) {
  if (["RANGE", "NUMBER_RANGE"].includes(definition.valueType) && value && typeof value === "object") { const range = value as { min?: number; max?: number }; return `${range.min ?? "?"}–${range.max ?? "?"}${definition.unit ? ` ${definition.unit}` : ""}`; }
  if (Array.isArray(value)) return value.join(", ");
  if (value && typeof value === "object") return Object.entries(value as Record<string, unknown>).filter(([, entry]) => entry !== "" && entry !== null && entry !== undefined).map(([key, entry]) => `${key}: ${Array.isArray(entry) ? entry.join(", ") : String(entry)}`).join(" · ");
  return `${value ?? ""}${definition.unit && typeof value === "number" ? ` ${definition.unit}` : ""}`;
}

function OptionGroup({ title, definitions, selected, role, onToggle, onClear, onValue, onUnknown, resolvedValues, editingId, setEditingId }: { title: string; definitions: CatalogDefinition[]; selected: Set<string>; role: Role; onToggle(item: CatalogDefinition): void; onClear(item: CatalogDefinition): void; onValue(item: CatalogDefinition, value: unknown): void; onUnknown(item: CatalogDefinition): void; resolvedValues: Map<string, unknown>; editingId: string | null; setEditingId(value: string | null): void }) { return <section className="wk-option-group"><h2>{title}</h2><div className="wk-option-grid">{definitions.map((item) => { const active = selected.has(item.id); const unlocked = isUnlocked(item, role); const boolean = item.valueType === "BOOLEAN"; const editing = editingId === item.id; return <div className="wk-option-wrap" data-selected={active} key={item.id}><button type="button" aria-pressed={active} aria-expanded={boolean ? undefined : editing} disabled={!unlocked} data-selected={active} onClick={() => boolean ? onToggle(item) : setEditingId(editing ? null : item.id)}><span className="wk-checkmark" aria-hidden="true">{active ? "✓" : boolean ? "" : "+"}</span><strong>{guidedLabel(item)}</strong>{active && !boolean && <small>{formatGuidedValue(item, resolvedValues.get(item.id))}</small>}{!unlocked && <small>{item.ownerAccess === "PRO" ? "Zusätzlicher Owner-Bereich (Entwurf)" : "Nur im Admin-Bereich bearbeitbar"}</small>}</button>{editing && unlocked && !boolean && <GuidedValueEditor definition={item} initialValue={resolvedValues.get(item.id)} onCancel={() => setEditingId(null)} onUnknown={() => { onUnknown(item); setEditingId(null); }} onClear={() => { onClear(item); setEditingId(null); }} onSave={(value) => { onValue(item, value); setEditingId(null); }} />}</div>; })}</div></section>; }

function GuidedValueEditor({ definition, initialValue, onSave, onUnknown, onClear, onCancel }: { definition: CatalogDefinition; initialValue: unknown; onSave(value: unknown): void; onUnknown(): void; onClear(): void; onCancel(): void }) {
  const objectValue = initialValue && typeof initialValue === "object" && !Array.isArray(initialValue) ? initialValue as Record<string, unknown> : definition.id === "operation-kitchen-hours" && Array.isArray(initialValue) ? { days: initialValue } : {};
  const [single, setSingle] = useState(typeof initialValue === "string" || typeof initialValue === "number" ? String(initialValue) : "");
  const [min, setMin] = useState(objectValue.min === undefined ? "" : String(objectValue.min));
  const [max, setMax] = useState(objectValue.max === undefined ? "" : String(objectValue.max));
  const [multiple, setMultiple] = useState<string[]>(Array.isArray(initialValue) ? initialValue.map(String) : []);
  const [structured, setStructured] = useState<Record<string, unknown>>(objectValue);
  const patch = (key: string, value: unknown) => setStructured((current) => ({ ...current, [key]: value }));
  const range = ["RANGE", "NUMBER_RANGE"].includes(definition.valueType);
  const numeric = ["NUMBER", "INTEGER", "DECIMAL", "MONEY"].includes(definition.valueType);
  const text = ["TEXT", "SHORT_TEXT", "LONG_TEXT", "URL", "PHONE", "TIME", "DATE"].includes(definition.valueType);
  const save = () => {
    if (range) { if (min === "" || max === "" || Number(min) > Number(max)) return; onSave({ min: Number(min), max: Number(max), unit: definition.unit }); return; }
    if (definition.valueType === "MULTI_SELECT") { if (!multiple.length) return; onSave(multiple); return; }
    if (definition.id === "operation-kitchen-hours") { onSave(Array.isArray(structured.days) ? structured.days : []); return; }
    if (["CONDITIONAL_RULE", "WEEKLY_SCHEDULE", "STRUCTURED_COMPOSITE"].includes(definition.valueType)) { onSave(structured); return; }
    if (!single.trim()) return; onSave(numeric ? Number(single) : single.trim());
  };
  return <div className="wk-value-editor" role="group" aria-label={`${guidedLabel(definition)} eingeben`}><p>{definition.description ?? "Ergänze einen konkreten Wert, damit Backyrd die Angabe sinnvoll verwenden kann."}</p>
    {range && <div className="wk-range-fields"><label><span>{definition.id === "character-group-range" ? "Gruppen von" : "Von"}</span><input autoFocus type="number" min="0" value={min} onChange={(event) => setMin(event.target.value)} /></label><label><span>bis</span><input type="number" min="0" value={max} onChange={(event) => setMax(event.target.value)} /></label>{definition.unit && <span>{definition.unit}</span>}</div>}
    {numeric && <label><span>Wert{definition.unit ? ` in ${definition.unit}` : ""}</span><input autoFocus type="number" min="0" step={definition.valueType === "DECIMAL" ? "0.1" : "1"} value={single} onChange={(event) => setSingle(event.target.value)} /></label>}
    {definition.valueType === "SINGLE_SELECT" && <label><span>Auswahl</span><select autoFocus value={single} onChange={(event) => setSingle(event.target.value)}><option value="">Bitte wählen</option>{definition.options?.map((option) => <option key={option}>{option}</option>)}</select></label>}
    {definition.valueType === "MULTI_SELECT" && <fieldset><legend>Passende Optionen</legend>{definition.options?.map((option) => <label key={option}><input type="checkbox" checked={multiple.includes(option)} onChange={(event) => setMultiple((current) => event.target.checked ? [...current, option] : current.filter((item) => item !== option))} />{option}</label>)}</fieldset>}
    {text && <label><span>{definition.valueType === "TIME" ? "Uhrzeit" : "Angabe"}</span>{definition.valueType === "LONG_TEXT" ? <textarea autoFocus value={single} onChange={(event) => setSingle(event.target.value)} /> : <input autoFocus type={definition.valueType === "TIME" ? "time" : definition.valueType === "DATE" ? "date" : definition.valueType === "URL" ? "url" : definition.valueType === "PHONE" ? "tel" : "text"} value={single} onChange={(event) => setSingle(event.target.value)} />}</label>}
    {definition.id === "constraint-age-rule" && <><div className="wk-structured-fields"><label><span>Mindestalter</span><input type="number" min="0" value={String(structured.minimumAge ?? "")} onChange={(event) => patch("minimumAge", Number(event.target.value))} /></label><label><span>Gilt</span><select value={String(structured.timing ?? "ALL_DAY")} onChange={(event) => patch("timing", event.target.value)}><option value="ALL_DAY">Ganztägig</option><option value="FROM_TIME">Ab einer Uhrzeit</option></select></label>{structured.timing === "FROM_TIME" && <label><span>Ab</span><input type="time" value={String(structured.fromTime ?? "")} onChange={(event) => patch("fromTime", event.target.value)} /></label>}<label><span>Betroffener Bereich</span><input value={String(structured.area ?? "Gesamter Spot")} onChange={(event) => patch("area", event.target.value)} /></label><label className="wide"><span>Sachliche Notiz</span><input value={String(structured.note ?? "")} onChange={(event) => patch("note", event.target.value)} /></label></div><WeekdayPicker value={Array.isArray(structured.days) ? structured.days.map(String) : []} onChange={(days) => patch("days", days)} /></>}
    {definition.id === "constraint-reservation-rule" && <><div className="wk-structured-fields"><label><span>Regel</span><select value={String(structured.mode ?? "RECOMMENDED")} onChange={(event) => patch("mode", event.target.value)}><option value="ALWAYS">Immer erforderlich</option><option value="RECOMMENDED">Empfohlen</option><option value="NOT_REQUIRED">Nicht erforderlich</option><option value="CONDITIONAL">Nur unter Bedingungen</option></select></label><label><span>Ab Gruppengröße</span><input type="number" min="1" value={String(structured.minGroupSize ?? "")} onChange={(event) => patch("minGroupSize", event.target.value ? Number(event.target.value) : null)} /></label><label><span>Ab Uhrzeit</span><input type="time" value={String(structured.startTime ?? "")} onChange={(event) => patch("startTime", event.target.value)} /></label><label><span>Bereich oder Angebot</span><input value={String(structured.area ?? "Gesamter Spot")} onChange={(event) => patch("area", event.target.value)} /></label></div><WeekdayPicker value={Array.isArray(structured.days) ? structured.days.map(String) : []} onChange={(days) => patch("days", days)} /></>}
    {definition.id === "operation-kitchen-hours" && <WeeklyValue value={structured} onChange={setStructured} />}
    {definition.id === "character-noise" && <div className="wk-structured-fields">{[["morning", "Morgens"], ["afternoon", "Nachmittags"], ["evening", "Abends"]].map(([key, label]) => <label key={key}><span>{label}</span><select value={String(structured[key] ?? "")} onChange={(event) => patch(key, event.target.value)}><option value="">Noch offen</option><option value="QUIET">Ruhig</option><option value="MODERATE">Mittel</option><option value="LIVELY">Lebhaft</option><option value="LOUD">Laut</option></select></label>)}</div>}
    <div className="wk-value-actions">{initialValue !== undefined && <button type="button" onClick={onClear}>Angabe entfernen</button>}<button type="button" onClick={onUnknown}>Noch unbekannt</button><button type="button" onClick={onCancel}>Abbrechen</button><button type="button" className="primary" onClick={save}>Übernehmen</button></div></div>;
}

function WeeklyValue({ value, onChange }: { value: Record<string, unknown>; onChange(value: Record<string, unknown>): void }) {
  const days = Array.isArray(value.days) ? value.days as OpeningDay[] : ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag"].map((day) => ({ day, enabled: false, open: "12:00", close: "21:30" }));
  const update = (index: number, patch: Partial<OpeningDay>) => onChange({ ...value, days: days.map((day, itemIndex) => itemIndex === index ? { ...day, ...patch } : day) });
  return <div className="wk-weekly-value"><strong>Küchenzeiten je Wochentag</strong>{days.map((day, index) => <div key={day.day}><label><input type="checkbox" checked={day.enabled} onChange={(event) => update(index, { enabled: event.target.checked })} />{day.day}</label>{day.enabled && <><input aria-label={`${day.day} Küche ab`} type="time" value={day.open} onChange={(event) => update(index, { open: event.target.value })} /><span>bis</span><input aria-label={`${day.day} Küche bis`} type="time" value={day.close} onChange={(event) => update(index, { close: event.target.value })} /></>}</div>)}</div>;
}

function WeekdayPicker({ value, onChange }: { value: string[]; onChange(value: string[]): void }) {
  return <fieldset><legend>Wochentage (leer = alle Tage)</legend>{["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"].map((day) => <label key={day}><input type="checkbox" checked={value.includes(day)} onChange={(event) => onChange(event.target.checked ? [...value, day] : value.filter((item) => item !== day))} />{day}</label>)}</fieldset>;
}

function FriendlyHours({ state, setState }: { state: PrototypeState; setState: Dispatch<SetStateAction<PrototypeState>> }) {
  const updateDay = (index: number, patch: Partial<PrototypeState["schedule"][number]>) => setState((current) => ({ ...current, scheduleConfirmed: true, schedule: current.schedule.map((day, i) => i === index ? { ...day, ...patch } : day) })); const addException = () => setState((current) => ({ ...current, scheduleConfirmed: true, exceptions: [...current.exceptions, { id: crypto.randomUUID(), date: "", state: "CLOSED", note: "" }] })); const updateException = (id: string, patch: Partial<PrototypeState["exceptions"][number]>) => setState((current) => ({ ...current, scheduleConfirmed: true, exceptions: current.exceptions.map((item) => item.id === id ? { ...item, ...patch } : item) }));
  const addObservation = () => { const now = new Date(); const until = new Date(now.getTime() + 4 * 60 * 60 * 1000); setState((current) => ({ ...current, currentObservations: [...current.currentObservations, { id: crypto.randomUUID(), type: "LIMITED", area: "Gesamter Spot", observedAt: now.toISOString(), validFrom: now.toISOString(), validUntil: until.toISOString(), sourceName: "Geführte Admin-Erfassung" }] })); };
  return <div className="wk-friendly-hours">{!state.scheduleConfirmed && <div className="wk-default-warning"><div><strong>Synthetischer Beispielplan – noch nicht bestätigt</strong><span>Die angezeigten Zeiten sind nur eine Vorlage und werden erst nach Bestätigung an die Engine gegeben.</span></div><button type="button" onClick={() => setState((current) => ({ ...current, scheduleConfirmed: true }))}>Zeiten bestätigen</button></div>}<div className="wk-hours-heading"><strong>Reguläre Woche</strong><span>{state.spot.timezone}</span></div>{state.schedule.map((item, index) => <div className="wk-hours-row" key={item.day}><label><input type="checkbox" checked={item.enabled} onChange={(event) => updateDay(index, { enabled: event.target.checked })} />{item.day}</label>{item.enabled ? <><input aria-label={`${item.day} öffnet`} type="time" value={item.open} onChange={(event) => updateDay(index, { open: event.target.value })} /><span>bis</span><input aria-label={`${item.day} schließt`} type="time" value={item.close} onChange={(event) => updateDay(index, { close: event.target.value })} /></> : <span className="wk-closed">Geschlossen</span>}</div>)}<div className="wk-exceptions"><div className="wk-hours-heading"><div><strong>Sonderöffnungszeiten</strong><small>Zum Beispiel Weihnachten, 1. August oder Neujahr.</small></div><button type="button" onClick={addException}>Sondertag hinzufügen</button></div>{state.exceptions.map((item) => <div className="wk-exception-row" key={item.id}><input aria-label="Datum des Sondertags" type="date" value={item.date} onChange={(event) => updateException(item.id, { date: event.target.value })} /><input aria-label="Name des Sondertags" value={item.note} onChange={(event) => updateException(item.id, { note: event.target.value })} placeholder="z. B. Neujahr" /><select aria-label="Status am Sondertag" value={item.state} onChange={(event) => updateException(item.id, { state: event.target.value })}><option value="CLOSED">Geschlossen</option><option value="OPEN">Sonderöffnungszeiten</option></select>{item.state === "OPEN" && <><input aria-label="Öffnet am Sondertag" type="time" value={item.open ?? ""} onChange={(event) => updateException(item.id, { open: event.target.value })} /><input aria-label="Schließt am Sondertag" type="time" value={item.close ?? ""} onChange={(event) => updateException(item.id, { close: event.target.value })} /></>}<button type="button" aria-label="Sondertag entfernen" onClick={() => setState((current) => ({ ...current, exceptions: current.exceptions.filter((entry) => entry.id !== item.id) }))}>×</button></div>)}</div><div className="wk-current-observations"><div className="wk-hours-heading"><div><strong>Aktuelle Abweichungen</strong><small>Jede Beobachtung benötigt Quelle und Ablaufzeit und wird nicht zur dauerhaften Eigenschaft.</small></div><button type="button" onClick={addObservation}>Aktuelle Abweichung hinzufügen</button></div>{state.currentObservations.map((item) => <div className="wk-observation-row" key={item.id}><select aria-label="Aktuelle Abweichung" value={item.type} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id ? { ...entry, type: event.target.value as PrototypeState["currentObservations"][number]["type"] } : entry) }))}><option value="CLOSED_TODAY">Heute geschlossen</option><option value="TEMPORARILY_CLOSED">Vorübergehend geschlossen</option><option value="KITCHEN_CLOSED">Küche aktuell geschlossen</option><option value="TERRACE_CLOSED">Terrasse aktuell geschlossen</option><option value="FULL">Ausgebucht</option><option value="LIMITED">Nur eingeschränkt verfügbar</option></select><input aria-label="Betroffener Bereich" value={item.area} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id ? { ...entry, area: event.target.value } : entry) }))} /><input aria-label="Beobachtet am" type="datetime-local" value={item.observedAt.slice(0, 16)} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id && event.target.value ? { ...entry, observedAt: new Date(event.target.value).toISOString() } : entry) }))} /><input aria-label="Gültig ab" type="datetime-local" value={item.validFrom.slice(0, 16)} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id && event.target.value ? { ...entry, validFrom: new Date(event.target.value).toISOString() } : entry) }))} /><input aria-label="Gültig bis" type="datetime-local" value={item.validUntil.slice(0, 16)} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id && event.target.value ? { ...entry, validUntil: new Date(event.target.value).toISOString() } : entry) }))} /><input aria-label="Quelle der aktuellen Abweichung" value={item.sourceName} onChange={(event) => setState((current) => ({ ...current, currentObservations: current.currentObservations.map((entry) => entry.id === item.id ? { ...entry, sourceName: event.target.value } : entry) }))} /><button type="button" aria-label="Aktuelle Abweichung entfernen" onClick={() => setState((current) => ({ ...current, currentObservations: current.currentObservations.filter((entry) => entry.id !== item.id) }))}>×</button></div>)}</div></div>;
}

function Review({ state, onSave, onAnalyze, onOpenExpert }: { state: PrototypeState; onSave(): void; onAnalyze(): void; onOpenExpert(): void }) {
  const resolved = resolveKnowledge(state); const derived = deriveFits(resolved); const issues = semanticIssues(state); const positive = resolved.filter((item) => isCompleteValue(item)); const incomplete = resolved.filter((item) => !isCompleteValue(item) && ["KNOWN_TRUE", "KNOWN_VALUE"].includes(item.status)); const byClass = (semanticClass: string) => positive.filter((item) => item.definition.semanticClass === semanticClass).map((item) => guidedLabel(item.definition)); const types = byClass("SUBCATEGORY"); const cuisines = [...byClass("CUISINE"), ...byClass("OFFERING")]; const fits = byClass("DIRECT_FIT"); const capabilities = byClass("CAPABILITY"); const amenities = positive.filter((item) => item.definition.semanticClass === "AMENITY").map((item) => guidedLabel(item.definition)); const constraints = positive.filter((item) => item.definition.domain === "CONSTRAINT").map((item) => guidedLabel(item.definition)); const unbacked = positive.filter((item) => !item.claims.some((claim) => claim.evidence.sourceName.trim())); const activeCurrent = engineSnapshot(state).currentState;
  return <section className="wk-review-v3"><div className="wk-preview-copy"><span className="wk-kicker">ANGABEN PRÜFEN</span><h2>Was Backyrd aktuell speichern und verwenden kann.</h2><p>Die mobile Ansicht ist nur eine unverbindliche Datenvorschau. Das spätere Produktdesign der Spotseite wird separat entschieden.</p><div className="wk-preview-checks"><div><strong>{state.spot.name && state.spot.address && state.spot.city ? "✓" : "○"} Grundprofil</strong><span>{state.spot.name && state.spot.address && state.spot.city ? "Name und Adresse sind bereit." : "Name, Adresse oder Ort fehlen noch."}</span></div><div><strong>✓ Hauptkategorie</strong><span>{catalog.categories.find((item) => item.key === state.spot.primaryCategory)?.label}</span></div><div><strong>{types.length ? "✓" : "○"} Klassifikation</strong><span>{[...types, ...cuisines].join(" · ") || "Noch offengelassen – das ist in Ordnung."}</span></div><div><strong>{capabilities.length} konkrete Möglichkeiten</strong><span>{capabilities.join(" · ") || "Noch keine Capability erfasst."}</span></div><div><strong>{amenities.length + constraints.length} Ausstattungen und Regeln</strong><span>{[...amenities, ...constraints].join(" · ") || "Noch keine konkrete Ausstattung oder Regel erfasst."}</span></div><div><strong>{state.scheduleConfirmed ? "✓" : "○"} Öffnungszeiten</strong><span>{state.scheduleConfirmed ? `Regulärer Wochenplan bestätigt; ${positive.some((item) => item.definition.id === "operation-kitchen-hours") ? "Küchenzeiten erfasst" : "Küchenzeiten noch offen"}.` : "Synthetischer Beispielplan noch nicht bestätigt."}</span></div><div><strong>{activeCurrent.length} aktuelle Abweichungen</strong><span>{activeCurrent.length ? activeCurrent.map((item) => item.type).join(" · ") : "Keine aktive temporäre Beobachtung."}</span></div><div><strong>{positive.length} verwendbare Angaben</strong><span>Optionale Katalogeinträge sind keine offenen Aufgaben. {unbacked.length ? `${unbacked.length} Angabe(n) haben noch keine belastbare Quelle.` : "Alle verwendbaren Angaben haben eine Quelle."}</span></div>{derived.length > 0 && <div><strong>{derived.length} vorsichtige Ableitung(en)</strong><span>{derived.map((item) => item.label).join(" · ")}</span></div>}{incomplete.length > 0 && <div className="warning"><strong>{incomplete.length} Angabe(n) brauchen Details</strong><span>{incomplete.map((item) => guidedLabel(item.definition)).join(" · ")}</span></div>}{issues.length > 0 && <div className="warning"><strong>{issues.length} semantische Prüfhinweise</strong><span>{issues.map((item) => item.title).join(" · ")}</span></div>}</div><div className="wk-review-actions"><button type="button" onClick={onSave}>Zwischenstand speichern</button><button type="button" onClick={onAnalyze}>Analyse starten →</button></div><button type="button" className="wk-review-expert" onClick={onOpenExpert}>Quellen und technische Vorschau öffnen</button></div><MobileSpotPreview state={state} types={types} cuisines={cuisines} fits={fits} amenities={amenities} /></section>;
}

function MobileSpotPreview({ state, types, cuisines, fits, amenities }: { state: PrototypeState; types: string[]; cuisines: string[]; fits: string[]; amenities: string[] }) {
  const today = state.schedule.find((item) => item.enabled); const highlights = amenities.slice(0, 3); const offer = cuisines.slice(0, 3); const line = (items: string[], fallback: string) => items.length ? items.join(" · ") : fallback;
  return <div><p className="wk-preview-draft-note">Unverbindliche Datenvorschau – kein finales Spot-Design</p><div className="wk-phone" aria-label="Mobile Datenvorschau des Spots"><div className="wk-phone-screen"><div className="wk-phone-hero"><div className="wk-phone-toolbar"><span>‹</span><div><span>↗</span><span>♡</span></div></div><div className="wk-phone-placeholder"><b>PC</b><small>Vorschaubild noch offen</small></div><div className="wk-phone-title"><div><span className="wk-open-dot">● {state.currentState.service === "CLOSED" ? "Geschlossen" : "Status nicht live geprüft"}</span>{state.spot.priceLevel && <span>{state.spot.priceLevel}</span>}</div><h3>{state.spot.name || "Name des Spots"}</h3><p>{state.spot.address || "Adresse"}, {state.spot.city || "Ort"}{state.spot.neighborhood ? ` · ${state.spot.neighborhood}` : ""}</p></div></div><div className="wk-phone-body"><div className="wk-phone-actions"><button type="button">⌁ Route</button><button type="button">＋ Moment</button></div><section className="wk-spot-profile"><small>DATENVORSCHAU</small><h4>Erfasster Inhalt</h4><PreviewRow label="Art des Ortes" value={line(types, "Noch keine Ortsart ausgewählt")} /><PreviewRow label="Besonderheit" value={state.spot.specialFeature || "Noch keine Besonderheit ergänzt"} /><PreviewRow label="Küche und Angebot" value={line(offer, "Noch keine Küche oder Angebotsform ausgewählt")} /></section>{highlights.length > 0 && <section className="wk-phone-section"><h4><i /> Ausstattung</h4><div className="wk-phone-chips">{highlights.map((item) => <span key={item}>{item} <b>✓</b></span>)}</div></section>}{fits.length > 0 && <section className="wk-phone-section"><h4><i /> Subjektive Eindrücke</h4><div className="wk-phone-chips">{fits.slice(0, 5).map((item) => <span key={item}>{item}</span>)}</div></section>}<section className="wk-phone-section wk-phone-info"><h4><i /> Grunddaten</h4><p>⌖ <span>{state.spot.address || "Adresse"}, {state.spot.city || "Ort"}</span></p>{state.spot.phone && <p>⌕ <span>{state.spot.phone}</span></p>}{state.spot.website && <p>◎ <span>{state.spot.website}</span></p>}</section><section className="wk-phone-section"><h4><i /> Öffnungszeiten</h4><div className="wk-today-card"><span>{state.scheduleConfirmed ? today?.day ?? "Keine Zeiten" : "Nicht bestätigt"}</span><strong>{state.scheduleConfirmed && today ? `${today.open}–${today.close}` : "Noch nicht engine-fähig"}</strong></div></section></div></div></div></div>;
}
function PreviewRow({ label, value }: { label: string; value: string }) { return <div className="wk-preview-row"><span>◇</span><div><small>{label}</small><strong>{value}</strong></div></div>; }

export function FriendlyAnalysis({ state, onOpenExpert }: { state: PrototypeState; onOpenExpert(): void }) {
  const report = analysisReport(state); const resolved = resolveKnowledge(state); const snapshot = engineSnapshot(state); const quality = qualityFor(state); const useful = resolved.filter(isCompleteValue).slice(0, 12); const conflicts = resolved.filter((item) => item.status === "DISPUTED"); const expired = resolved.filter((item) => item.status === "EXPIRED"); const issues = semanticIssues(state); const suggestions = [resolved.some((item) => item.definition.semanticClass === "SUBCATEGORY") ? null : "Art des Ortes ergänzen", resolved.some((item) => item.definition.semanticClass === "CAPABILITY") ? null : "Konkrete Möglichkeiten des Spots ergänzen", state.scheduleConfirmed ? null : "Reguläre Öffnungszeiten bestätigen"].filter(Boolean) as string[];
  return <main className="wk-friendly-analysis"><div className="wk-analysis-hero"><span>ANALYSE ABGESCHLOSSEN</span><h1>Das weiß Backyrd über {state.spot.name}.</h1><p>{quality.knownFacts} verwendbare Fakten aus {quality.answeredQuestions} ausdrücklich bearbeiteten Fragen. Die technische Katalogabdeckung von {quality.technicalCatalogCoverage}% ist eine Diagnose des großen Definitionskatalogs – kein Qualitätsurteil und kein Ranking-Signal.</p></div><div className="wk-analysis-summary"><div><span>Grundprofil</span><strong>{quality.profile.completed}/{quality.profile.total}</strong></div><div><span>Verwendbare Fakten</span><strong>{quality.knownFacts}</strong></div><div><span>Vorsichtige Ableitungen</span><strong>{snapshot.derivedKnowledge.length}</strong></div></div><section><h2>Das ist bereits besonders nützlich</h2>{useful.length ? <div className="wk-friendly-tags">{useful.map((item) => <span key={item.definition.id}>{guidedLabel(item.definition)}</span>)}</div> : <p>Noch keine inhaltlichen Angaben ausgewählt. Der Spot bleibt trotzdem gültig gespeichert.</p>}</section><section><h2>Hilfreiche Ergänzungen</h2>{suggestions.length ? <ul>{suggestions.map((item) => <li key={item}>{item}</li>)}</ul> : <p>Für diesen Prototypstand sind die zentralen Bereiche bearbeitet.</p>}</section><div className="wk-analysis-alerts"><section><h2>Widersprüche und Prüfhinweise</h2><p>{conflicts.length || issues.length ? [...conflicts.map((item) => guidedLabel(item.definition)), ...issues.map((item) => item.title)].join(" · ") : "Keine Widersprüche erkannt."}</p></section><section><h2>Möglicherweise veraltet</h2><p>{expired.length ? expired.map((item) => guidedLabel(item.definition)).join(" · ") : "Keine abgelaufenen Angaben erkannt."}</p></section></div><section className="wk-engine-readable"><div><h2>So wird der Spot aktuell übergeben</h2><p>{snapshot.cuisine.length + snapshot.offering.length + snapshot.capabilities.length + snapshot.amenities.length + snapshot.hardConstraints.length + snapshot.operationalModel.facts.length} strukturierte Einträge, {snapshot.directSubjectiveClaims.length} subjektive Angaben und {snapshot.derivedKnowledge.length} abgeleitete Hinweise. Nutzer-Intents, Abo-, Payment- und private Quelldaten fehlen bewusst.</p></div><button type="button" onClick={onOpenExpert}>Technische Vorschau öffnen →</button></section><details><summary>Vollständige technische Analyse anzeigen</summary><pre>{JSON.stringify(report, null, 2)}</pre></details></main>;
}
